import SwiftUI

// Pub crawl mode for TubeNavigator v1.3.
// 326 pubs imported 17 Nov 2026 from Jeffery's "Historic Pubs of London
// Catalogue" spreadsheet (ChatGPT-built app/PWA export), plus the Spaniards
// Inn, which is on his original list but not in the catalogue — 327 in all.
//
// Audit of the spreadsheet (17 Nov 2026): 326 data rows, no blank rows,
// no missing names, Pub IDs, addresses, coordinates or Closest Tube values,
// no duplicate Pub IDs, no duplicate name+address pairs, no duplicate
// coordinates. 24 names repeat (e.g. four Red Lions, four Ships, three
// Kings Arms) but every one is a different pub at a different address, so
// all were kept. The "Area" column is blank for the 30 Jeff's-list pubs;
// their area below is the street taken from the address.
//
// Nearest station: straight-line (haversine) distance from the pub's
// coordinates to the 97 Tube/DLR/Elizabeth line stations in the app, using
// station coordinates from TfL StopPoint/Mode/tube,dlr,elizabeth-line,
// checked 17 Nov 2026. Median distance 0.37 km; 261 of 326 within 1 km.
// 27 pubs are over 2 km from any station in the app and 8 are over 5 km
// (three around High Barnet, four around Hatch End/Harrow, one in Whetstone)
// — the catalogue's own Closest Tube suggestion (e.g. High Barnet, an
// Overground station, or a Zone 3-5 Tube station) is kept on each pub so
// the local station is not lost. v1.6 (19 Nov 2026): lat/lon kept on every
// pub so a journey can start/end at the pub itself (TfL routes from
// coordinates, with a walking leg to the nearest station). 89 pubs' computed nearest differs from
// the catalogue suggestion, mostly because the suggestion is an Overground
// or DLR station outside the app's list, or a nearby alternative.

struct Pub: Identifiable, Hashable {
    // The catalogue Pub ID is unique across all 326 rows, so it is the id.
    // Name alone is not unique — there are four Red Lions.
    var id: String { sourceId }
    let sourceId: String
    let name: String
    let area: String
    let address: String
    let lat: Double         // v1.6: for journey endpoints — plan from the pub itself
    let lon: Double
    let stationId: String   // nearest Tube/DLR/Elizabeth line station in the app
    let nearestKm: Double?  // straight-line distance to that station, if known
    let closestTube: String // the catalogue's own Closest Tube suggestion
    let whyGo: String?
    let hours: String?

    var station: Station? { StationData.station(id: stationId) }
    var stationName: String { station?.name ?? area }
    var distanceText: String? {
        guard let km = nearestKm else { return nil }
        if km < 1 { return "\(Int(km * 1000)) m" }
        return String(format: "%.1f km", km)
    }
    var isFarFromTube: Bool { (nearestKm ?? 0) > 2 }
}

struct PubStop: Identifiable, Hashable {
    var id: String { name }
    let name: String
    let stationId: String

    var station: Station? { StationData.station(id: stationId) }
    var stationName: String { station?.name ?? "" }
}

