// MARK: - Pub crawl view

struct PubCrawlView: View {
    @EnvironmentObject private var service: TubeService
    @Environment(\.dismiss) private var dismiss
    @State private var searchText = ""
    @State private var selectedPub: Pub?

    private var filteredPubs: [Pub] {
        guard !searchText.isEmpty else { return PubData.all }
        let needle = searchText.lowercased()
        return PubData.all.filter { pub in
            pub.name.lowercased().contains(needle)
                || pub.area.lowercased().contains(needle)
                || pub.stationName.lowercased().contains(needle)
                || pub.address.lowercased().contains(needle)
        }
    }

    var body: some View {
        List {
            Section("First day — the usual route") {
                ForEach(Array(PubData.firstDay.enumerated()), id: \.element.id) { index, stop in
                    HStack {
                        VStack(alignment: .leading, spacing: 2) {
                            Text("\(index + 1). \(stop.name)")
                            Text("Nearest station: \(stop.stationName)")
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                        Spacer()
                        Button("Plan leg") {
                            planLeg(to: stop)
                        }
                        .buttonStyle(.bordered)
                    }
                }
                Text("The first leg starts from your current From station. Each later leg starts at the previous stop.")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
            Section("All pubs (\(PubData.all.count))") {
                ForEach(filteredPubs) { pub in
                    HStack {
                        Button { selectedPub = pub } label: {
                            VStack(alignment: .leading, spacing: 2) {
                                Text(pub.name)
                                Text("\(pub.area) · nearest: \(pub.stationName)\(pub.distanceText.map { " (\($0))" } ?? "")")
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                            }
                        }
                        Spacer()
                        // v1.7: star a pub — it joins the Favourites on the
                        // Places tab and comes first in Plan suggestions.
                        Button {
                            service.toggleFavouritePub(pub)
                        } label: {
                            Image(systemName: service.isFavouritePub(pub) ? "star.fill" : "star")
                                .foregroundStyle(.yellow)
                        }
                        .buttonStyle(.plain)
                    }
                }
                Text("Tap a pub for its details and to plan the journey. Nearest station is the closest Tube, DLR or Elizabeth line station in the app; a few outer-London pubs are a long way from any of those, and the catalogue's own suggestion is shown on each pub.")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
        }
        .navigationTitle("Pub crawl")
        .searchable(text: $searchText, prompt: "Search pubs, areas, stations")
        .sheet(item: $selectedPub) { pub in PubDetailView(pub: pub) }
    }

    private func planLeg(to stop: PubStop) {
        if let idx = PubData.firstDay.firstIndex(where: { $0.id == stop.id }), idx > 0 {
            service.fromEndpoint = PubData.firstDay[idx - 1].station.map(Endpoint.station)
        }
        service.toEndpoint = stop.station.map(Endpoint.station)
        Task { await service.planJourney() }
        dismiss()
    }
}

// MARK: - Pub detail

struct PubDetailView: View {
    @EnvironmentObject private var service: TubeService
    @Environment(\.dismiss) private var dismiss
    let pub: Pub

    var body: some View {
        NavigationStack {
            List {
                Section {
                    LabeledContent("Nearest station", value: pub.stationName + (pub.distanceText.map { " (\($0) away)" } ?? ""))
                    if pub.closestTube.lowercased() != pub.stationName.lowercased() {
                        LabeledContent("Catalogue suggests", value: pub.closestTube)
                    }
                    LabeledContent("Address", value: pub.address)
                }
                if pub.isFarFromTube {
                    Section {
                        Text("This one is a trek from the Tube — the catalogue suggests \(pub.closestTube) instead, which is not a Tube, DLR or Elizabeth line station in this app.")
                            .font(.callout)
                    }
                }
                if let why = pub.whyGo {
                    Section("Why go") { Text(why) }
                }
                if let hours = pub.hours {
                    Section("Opening hours") { Text(hours) }
                }
                Section {
                    // v1.7: star it — favourite pubs sit in Favourites on
                    // the Places tab and come first in Plan suggestions.
                    Button(service.isFavouritePub(pub) ? "Remove from favourites" : "Add to favourites") {
                        service.toggleFavouritePub(pub)
                    }
                }
                Section {
                    // v1.6: plans to the pub itself — TfL routes from its
                    // coordinates, with the walk from the station included.
                    Button("Plan journey to this pub") {
                        service.toEndpoint = .pub(pub)
                        Task { await service.planJourney() }
                        dismiss()
                    }
                }
            }
            .navigationTitle(pub.name)
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Done") { dismiss() }
                }
            }
        }
    }
}

